def case(cid,title,material,task,solution,transfer,transfer_solution,limits,rubric):
    d={'id':cid,'titleDe':title[0],'titleEn':title[1],'syntheticData':True,'actualExperimentPerformed':False}
    for key,v in [('material',material),('task',task),('workedSolution',solution),('freshTransfer',transfer),('freshTransferSolution',transfer_solution),('limits',limits)]:
        d[key+'De']=v[0];d[key+'En']=v[1]
    d['rubric']={'totalPoints':10,'criteria':[{'id':f'{cid}-criterion-{i+1}','points':score,'criterionDe':a,'criterionEn':b} for i,(score,a,b) in enumerate(rubric)],'masteryClaim':'Candidate rubric only; no learner performance, human approval or actual trial established.'}
    assert sum(x['points'] for x in d['rubric']['criteria'])==10
    return d
def add(i,archetype,exps,axes,cases,reason):
    expectations=[{'id':f'e{j+1}','essentialUnderstandingDe':a,'essentialUnderstandingEn':b,'observablePerformanceDe':c,'observablePerformanceEn':d} for j,(a,b,c,d) in enumerate(exps)]
    profile={'archetype':archetype,'expectations':expectations,'coverageExpectations':{'requiredExpectationIds':[x['id'] for x in expectations],'alternativeExpectationGroups':[],'minimumIndependentDemonstrations':2,'freshVariationRequired':True,'independentTransferRequired':True},'variationAxes':[{'id':f'v{j+1}','textDe':a,'textEn':b} for j,(a,b) in enumerate(axes)],'applicationCaseBriefs':[{'id':c['id'],'taskDemandDe':c['taskDe'],'taskDemandEn':c['taskEn'],'expectedPerformanceDe':c['workedSolutionDe'],'expectedPerformanceEn':c['workedSolutionEn'],'understandingFocusDe':' / '.join(e['essentialUnderstandingDe'] for e in expectations),'understandingFocusEn':' / '.join(e['essentialUnderstandingEn'] for e in expectations)} for c in cases]}
    DATA.append({'goalId':IDS[i],'wholeCurrentGoal':GOALS[IDS[i]],'authorDecision':'KEEP current whole DE/EN descriptions; candidate material only; source scope finding separate','profile':profile,'wholeMaterialCases':cases,'reason':reason,'status':'needs_human_review','reviewAuthority':'ai_candidate','evidenceLevel':'E1','maximumClaimScope':'G1','reviewId':RID,'humanApproval':False,'humanTrial':False})

add(0,'representation',[
('Licht wird in der Netzhaut in neuronale Information umgewandelt; Ganglienzellaxone bilden den Sehnerv.','Light is transduced in the retina into neural information; ganglion-cell axons form the optic nerve.','Ordnet Rezeptor, retinale Verarbeitung und afferente Leitung mit verschiedenen Funktionen.','Orders receptors, retinal processing and afferent conduction with distinct functions.'),
('Nasale Netzhautfasern kreuzen am Chiasma, temporale nicht; eine Hemisphäre verarbeitet das gegenüberliegende Gesichtsfeld beider Augen.','Nasal retinal fibers cross at the chiasm; temporal fibers do not. Each hemisphere processes the opposite visual hemifield from both eyes.','Verfolgt ein angegebenes Gesichtsfeld über die Kreuzung statt einfach Augen und Hemisphären gleichzusetzen.','Traces a given hemifield through the crossing rather than equating eyes with hemispheres.'),
('Die bewusste visuelle Verarbeitung umfasst Thalamus, Sehrinde und weitere Netzwerke; ein Schema ist keine Diagnose.','Conscious visual processing involves thalamic relay, visual cortex and further networks; a schematic is not a diagnosis.','Zeichnet die Hauptbahn einschließlich Relais und kortikaler Verarbeitung und begrenzt Störungsfolgerungen.','Traces the main pathway including relay and cortical processing and bounds disruption inferences.')],
[('Gesichtsfeld links/rechts und Ort einer vorgegebenen Unterbrechung.','Left/right hemifield and site of a stipulated interruption.'),('Wegschema gegenüber begründeter funktionaler Vorhersage.','Pathway diagram versus justified functional prediction.')],[
case('visual-route','Hauptbahn nachzeichnen / Trace the main pathway'.split(' / '),
('Modellkarten: Licht; Fotorezeptor; Bipolarzelle; Ganglienzelle; Sehnerv; Chiasma; Thalamus (Corpus geniculatum laterale); Sehstrahlung; Sehrinde. Modellregel: Das rechte Gesichtsfeld trifft links auf beide Netzhäute; nasale Fasern kreuzen, temporale bleiben auf ihrer Seite.','Model cards: light; photoreceptor; bipolar cell; ganglion cell; optic nerve; chiasm; thalamic lateral geniculate nucleus; optic radiation; visual cortex. Rule: the right visual field falls on the left side of both retinas; nasal fibers cross and temporal fibers stay ipsilateral.'),
('Ordne die Hauptbahn, kennzeichne die Transduktion und zeichne für das rechte Gesichtsfeld die Wege beider Augen zur Sehrinde.','Order the main pathway, mark transduction, and trace both eyes\' pathways for the right visual hemifield to visual cortex.'),
('Fotorezeptor → Bipolarzelle → Ganglienzelle → Sehnerv → Chiasma → CGL → Sehstrahlung → Sehrinde. Transduktion erfolgt am Fotorezeptor, nicht im Sehnerv. Rechts im Gesichtsfeld: im rechten Auge nasale Netzhaut, daher Kreuzung; im linken Auge temporale Netzhaut, daher keine Kreuzung. Beide Wege erreichen die linke Sehrinde. Weitere Verarbeitung ist verteilt; das Schema zeigt die Hauptbahn.','Photoreceptor → bipolar cell → ganglion cell → optic nerve → chiasm → LGN → optic radiation → visual cortex. Transduction is at photoreceptors, not in the nerve. The right visual field reaches the right eye\'s nasal retina, which crosses, and the left eye\'s temporal retina, which does not. Both reach left visual cortex. Further processing is distributed; this is the principal pathway.'),
('Zeichne ohne die Karten das linke Gesichtsfeld und erkläre, weshalb ein Auge nicht nur eine Hemisphäre versorgt.','Without the cards, trace the left visual field and explain why one eye supplies more than one hemisphere.'),
('Linkes Gesichtsfeld: linkes Auge nasal/kreuzend, rechtes Auge temporal/ungekreuzt → rechte Sehrinde. Jedes Auge enthält nasale und temporale Netzhaut und teilt seine afferenten Informationen auf.','Left field: left eye nasal/crossing and right eye temporal/uncrossed → right visual cortex. Each eye contains nasal and temporal retina and splits its afferent information.'),
('Kein detaillierter Zellschaltplan; keine Aussage über einzelne Patient:innen.','Not a complete retinal circuit or a claim about individual patients.'),[(4,'Hauptbahn und Transduktion korrekt.','Correct main pathway and transduction.'),(4,'Beide Gesichtsfeldwege und partielle Kreuzung korrekt.','Correct hemifield pathways and partial crossing.'),(2,'Hauptbahnmodell und weitere Verarbeitung unterschieden.','Distinguishes main-pathway model from further processing.')]),
case('visual-interruption',('Modellunterbrechungen','Model interruptions'),
('Rein hypothetisches Schema mit denselben Kreuzungsregeln: A unterbricht alle Fasern des linken Sehnervs vor dem Chiasma; B nur die kreuzenden nasalen Fasern im Chiasma. Das zeitliche Gesichtsfeld projiziert auf die nasale Netzhaut.','Purely hypothetical schematic with the same crossing rules: A interrupts every left optic-nerve fiber before the chiasm; B interrupts only crossing nasal fibers in the chiasm. Temporal visual field projects onto nasal retina.'),
('Vergleiche A und B: Welche Information fehlt? Begründe am Faserverlauf und benenne eine Grenze.','Compare A and B: what information is lost? Justify using the fiber paths and state a limit.'),
('A nimmt die Information des gesamten linken Auges, nicht das gesamte linke Gesichtsfeld beider Augen. B nimmt die temporalen Gesichtsfeldanteile beider Augen, weil deren nasale Netzhautfasern kreuzen. Die genauen Ausfälle echter Erkrankungen folgen daraus nicht ohne weitere Untersuchung.','A removes information from the entire left eye, not the entire left hemifield of both eyes. B removes temporal visual-field information from both eyes because nasal retinal fibers cross. Exact deficits in real disease require further examination.'),
('C unterbricht im Modell alle Fasern des linken Tractus opticus hinter dem Chiasma. Welche Gesichtsfeldseite betrifft das?','C interrupts all left optic-tract fibers after the chiasm in the model. Which visual hemifield is affected?'),
('Das rechte Gesichtsfeld beider Augen: rechts nasale Fasern sind gekreuzt, links temporale nicht; beide liegen im linken Tractus.','The right visual hemifield from both eyes: right nasal fibers have crossed and left temporal fibers have not; both travel in the left tract.'),
('Vollständige modellierte Unterbrechung ist keine klinische Diagnose oder Verlaufsvorhersage.','A complete modeled interruption is not a clinical diagnosis or prognosis.'),[(4,'A richtig vom hemifeldbezogenen Ausfall unterschieden.','Correctly distinguishes A from a hemifield deficit.'),(4,'B und C am Faserverlauf begründet.','Justifies B and C using fiber paths.'),(2,'Klinische Grenze benannt.','States clinical limit.')])],
'Whole-profile candidate covers transduction, main route, partial crossing and causal tracing in two independent representations. Source precision and course holds are separately open.')

add(1,'modeling',[
('Verarbeitung ist die Zusammenarbeit verbundener Hirnareale, nicht ein universelles Einzelzentrum.','Processing is cooperation among connected brain areas, not one universal center.','Verknüpft wahrgenommene Information, Erkennen und Handlungsplanung im gegebenen Netzwerk.','Connects perceived information, recognition and action planning in the supplied network.'),
('Eine Störung kann Übertragung oder eine Verarbeitungskomponente betreffen und lässt sich nur begrenzt funktional deuten.','Disruption can affect transmission or a processing component and allows only bounded functional interpretation.','Leitet erhaltene und beeinträchtigte Leistungen aus vorgegebenen Funktionsausfällen ab.','Derives retained and impaired performance from stipulated functional failures.'),
('Beobachtete Leistung allein identifiziert kein eindeutiges Hirnareal oder eine Erkrankung.','Observed performance alone does not uniquely identify a brain area or disease.','Unterscheidet modellgestützte Erklärung von medizinischer Diagnose und berücksichtigt Alternativen.','Distinguishes model explanation from medical diagnosis and considers alternatives.')],
[('Visuelle Verarbeitung versus Lernen und Abrufen.','Visual processing versus learning and retrieval.'),('Verbindungsunterbrechung versus vermindertes Signal und Alternativerklärung.','Connection interruption versus reduced signal and alternative explanations.')],[
case('brain-object',('Vom Signal zur Handlung','From signal to action'),
('Fiktives Netzwerk: S erfasst einfache visuelle Merkmale; R verknüpft sie mit bekannten Gegenständen; P plant eine zielgerichtete Handbewegung; C koordiniert deren Ausführung. Verbindungen S→R→P→C. In Modell X bleibt S erhalten, R ist blockiert; Muskelkraft und C sind intakt.','Fictitious network: S extracts simple visual features; R links them to familiar objects; P plans a targeted hand movement; C coordinates execution. Links S→R→P→C. In model X, S is intact but R blocked; muscle strength and C are intact.'),
('Erkläre das normale Zusammenspiel beim Greifen einer Tasse und begründe, was X erschwert und was erhalten bleibt.','Explain normal cooperation when grasping a cup and justify what X impairs and preserves.'),
('Merkmale werden erfasst, als Tasse erkannt, ein Griff geplant und koordiniert ausgeführt. Bei X können Merkmale noch registriert und einfache Bewegungen ausgeführt werden; das gegenstandsbezogene Erkennen und darauf aufbauende Planen werden erschwert. Intakte Muskelkraft ersetzt R nicht. Reale Funktionen liegen in Netzwerken, die Buchstaben sind Funktionsmodule.','Features are extracted, recognized as a cup, a grasp is planned and executed with coordination. X preserves registration of features and simple movement but impairs object recognition and planning based on it. Intact strength cannot replace R. Real functions are networked; letters denote functional modules.'),
('Im neuen Modell Y sind S, R und P intakt, aber die Verbindung P→C ist unterbrochen. Deute den Unterschied zu X.','In new model Y, S, R and P are intact but P→C is interrupted. Interpret the difference from X.'),
('Erkennen und Planen bleiben in Y möglich, die Weiterleitung zur koordinierten Ausführung ist gestört. X betrifft bereits Erkennen. Beide können auffälliges Greifen zeigen, aber unterschiedliche Modellursachen haben.','Recognition and planning remain possible in Y, but transmission to coordinated execution fails. X already impairs recognition. Both may show unusual grasping while having different modeled causes.'),
('Keine Patientendaten, keine Lokalisation oder Diagnose aus einer Alltagsszene.','No patient data, localization or diagnosis from an everyday scene.'),[(4,'Vollständiges Zusammenwirken erklärt.','Explains complete cooperation.'),(4,'Erhaltene und beeinträchtigte Funktionen in X/Y begründet.','Justifies retained/impaired functions in X/Y.'),(2,'Modellmodule und echte Hirnnetzwerke getrennt.','Separates model modules from real networks.')]),
case('brain-memory',('Lernen und Abrufen im Netzwerk','Learning and retrieval in a network'),
('Synthetisches Modell: Aufmerksamkeit A ermöglicht Aufnahme; Hippocampus-Netzwerk H unterstützt Bildung neuer episodischer Erinnerungen; verteilte kortikale Netzwerke K sind an längerfristiger Speicherung beteiligt. Ein bereits gut bekannter Weg und ein neu gelernter Weg werden verglichen; H arbeitet vorübergehend eingeschränkt, A und K sind unverändert.','Synthetic model: attention A enables encoding; hippocampal network H supports formation of new episodic memories; distributed cortical networks K participate in longer-term storage. A familiar route and a newly learned route are compared; H is temporarily reduced while A and K are unchanged.'),
('Erkläre, weshalb neue Wege stärker betroffen sein können als vertraute. Nenne eine andere Ursache für schwache Leistung und eine unterscheidende Prüfung.','Explain why new routes may be more affected than familiar ones. Give an alternative cause of weak performance and a discriminating check.'),
('Die Aufnahme neuer episodischer Zusammenhänge benötigt im Modell H; vertraute Inhalte sind bereits in weiteren Netzwerken eingebunden. Daher kann Neueslernen stärker beeinträchtigt sein. Verminderte Aufmerksamkeit könnte ähnlich aussehen; unter standardisierter Aufmerksamkeit und mit Vergleich bekannter/neuer Inhalte lässt sich diese Alternative prüfen. Das Modell behauptet keine ausschließlich hippocampale Speicherung.','Formation of new episodic associations uses H in the model; familiar information is already embedded in other networks. New learning can thus be more impaired. Reduced attention could look similar; standardizing attention and comparing familiar/new content tests that alternative. The model does not claim exclusively hippocampal storage.'),
('Bei Ablenkung wird Leistung für bekannte und neue Wege schlechter. Passt das eindeutig zu einer H-Störung?','With distraction, performance worsens for familiar and new routes. Does this uniquely support an H disturbance?'),
('Nein. Der gemeinsame Einbruch passt auch zu Aufmerksamkeit/Abrufbedingungen. Mehrere kontrollierte Vergleiche wären nötig; aus dem Ergebnis folgt keine Erkrankung.','No. The shared decline also fits attention or retrieval conditions. Further controlled comparisons are needed; the result does not identify a disease.'),
('Qualitatives Unterrichtsmodell; keine Gedächtnisdiagnostik.','Qualitative teaching model; not memory diagnostics.'),[(4,'Neulernen versus vertraute Speicherung nachvollziehbar erklärt.','Explains new learning versus familiar storage.'),(4,'Alternative und Kontrollvergleich sinnvoll.','Provides relevant alternative and control comparison.'),(2,'Nicht-exklusive Netzwerke und Diagnosegrenze benannt.','Notes distributed networks and diagnostic limit.')])],
'Candidate distinguishes causal interpretation of processing and disruption from the separate overview goal. No claims of diagnosis; HE basic/advanced source scope remains separately held.')

add(2,'concept',[
('Nozizeption ist neuronale Verarbeitung potenziell schädigender Reize; Schmerz ist eine persönliche Erfahrung und nicht damit identisch.','Nociception is neural processing of potentially damaging stimuli; pain is a personal experience and not identical to it.','Unterscheidet periphere Reizaufnahme, neuronale Aktivität, Reflex und berichteten Schmerz.','Distinguishes peripheral sensing, neural activity, reflex and reported pain.'),
('Periphere und spinale Verarbeitung sowie aufsteigende und absteigende Wege beeinflussen die Weiterleitung.','Peripheral and spinal processing and ascending/descending pathways affect transmission.','Erklärt am Schema einen Reflex sowie zentrale Modulation ohne einen einzigen Schmerzzentrum-Anspruch.','Explains a reflex and central modulation without claiming one pain center.'),
('Sensibilisierung und hemmende/fördernde Modulation können Antwortänderungen bei ähnlichem Eingangssignal erklären.','Sensitization and inhibitory/facilitatory modulation can explain changed responses to similar inputs.','Interpretiert vorgegebene Daten mit Alternativen, ohne Schmerzerleben oder Erkrankungen aus Impulszahlen abzuleiten.','Interprets stipulated data with alternatives without deriving pain experience or disease from impulse counts.')],
[('Früher Reflex versus bewusste Erfahrung.','Early reflex versus conscious experience.'),('Konstanter Reiz mit geänderter Verarbeitung und umgekehrter Übertragungsrichtung.','Constant input with changed processing and reverse pathway direction.')],[
case('nociception-reflex',('Reflex und Schmerzerleben','Reflex and pain experience'),
('Erfundene Zeitlinie, kein Menschenversuch: reizbezogenes Signal im sensorischen Nerv bei t=0; spinaler Reflexweg aktiviert einen Muskel bei t=40; ein bewusster Bericht wird erst bei t=180 abgegeben. Zeitwerte sind Modellwerte, keine typischen medizinischen Latenzen.','Invented timeline, no human experiment: stimulus-related sensory-nerve signal at t=0; spinal reflex route activates muscle at t=40; a conscious report is given only at t=180. Values are model values, not typical medical latencies.'),
('Erkläre die zwei Wege und warum der Reflex vor dem Bericht auftreten kann. Setze Nozizeption nicht mit Schmerz gleich.','Explain the two routes and why reflex can precede the report. Do not equate nociception with pain.'),
('Periphere sensorische Endigungen liefern ein Signal. Im Rückenmark kann ein Reflexkreis motorische Aktivität auslösen, während aufsteigende Information zentrale Netzwerke erreicht. Ein bewusster Bericht benötigt zusätzliche Verarbeitung und Handlung. Früher Reflex beweist weder ein bestimmtes Schmerzerleben noch dessen Fehlen; Impulsaktivität allein misst die persönliche Erfahrung nicht.','Peripheral sensory endings provide a signal. A spinal reflex circuit can activate movement while ascending information reaches central networks. Conscious reporting requires additional processing and action. An early reflex proves neither a specific pain experience nor its absence; impulses alone do not measure the personal experience.'),
('In einem Modell bleibt ein spinaler Reflex erhalten, der aufsteigende Weg ist unterbrochen. Was darf man folgern?','In a model, spinal reflex remains but the ascending pathway is interrupted. What can be inferred?'),
('Der lokale Reflex benötigt diesen aufsteigenden Weg nicht. Die zentrale Information dieses Wegs fehlt im Modell; daraus folgt keine vollständige Aussage über das Erleben einer realen Person.','The local reflex does not require that ascending route. Central information from this route is absent in the model; this does not fully determine a real person\'s experience.'),
('Keine Schmerzprovokation, Diagnose oder Therapieempfehlung.','No pain provocation, diagnosis or treatment advice.'),[(4,'Peripherer Eingang und spinaler/aufsteigender Weg korrekt.','Correct peripheral input and spinal/ascending routes.'),(4,'Reflex, Bericht und Erfahrung differenziert.','Distinguishes reflex, report and experience.'),(2,'Persönliche Erfahrung nicht aus Nervenaktivität abgeleitet.','Does not infer personal experience from neural activity.')]),
case('nociception-modulation',('Veränderter Durchlass','Changed transmission'),
('Synthetische Modellwerte: gleiche periphere Aktivität 20 Einheiten. Ohne zusätzliches absteigendes Signal leitet der spinale Ausgang 12 Einheiten weiter; mit hemmendem Signal 5, mit förderndem Signal 16. Die Einheiten sind keine Schmerzskala.','Synthetic model values: peripheral activity fixed at 20 units. Without extra descending signal, spinal output transmits 12 units; with inhibitory input 5 and facilitatory input 16. Units are not a pain scale.'),
('Zeichne Eingang, spinalen Ausgang und absteigenden Einfluss. Erkläre Hemmung/Förderung und begrenze die Interpretation.','Draw input, spinal output and descending influence. Explain inhibition/facilitation and bound interpretation.'),
('Das unveränderte Eingangssignal wird spinal unterschiedlich weitergeleitet. Absteigende Aktivität kann den Durchlass hemmen oder fördern; sie läuft vom Gehirn zur spinalen Verarbeitung und verändert dort die aufsteigende Information. 5 oder 16 Einheiten sind nicht direkt ein individueller Schmerzbericht. Alternative Erklärungen echter Befunde würden Messfehler oder andere Eingänge einschließen.','The unchanged input is transmitted differently at spinal level. Descending activity can inhibit or facilitate transmission; it travels from brain to spinal processing and changes ascending information there. Five or sixteen units are not an individual pain report. Real findings also require consideration of measurement error or other inputs.'),
('Nach wiederholtem Reiz ergibt derselbe Eingang mehr Ausgang, auch ohne geändertes absteigendes Signal. Nenne einen passenden Mechanismus.','After repeated stimulus, the same input produces greater output even without changed descending input. Name a compatible mechanism.'),
('Erhöhte zentrale Erregbarkeit/Sensibilisierung könnte die Weiterleitung verstärken. Das ist eine mögliche Modellerklärung, keine Diagnose und kein Beweis, dass Schmerz eingebildet ist.','Increased central excitability/sensitization could enhance transmission. This is a possible model explanation, not a diagnosis or evidence that pain is imaginary.'),
('Keine lineare Nervensignal-zu-Schmerz-Gleichung; keine klinische Ursachenfeststellung.','No linear neural-signal-to-pain equation or clinical causal determination.'),[(4,'Beide Richtungen und spinaler Einfluss korrekt.','Correct directions and spinal influence.'),(4,'Hemmung, Förderung und Transfermechanismus erklärt.','Explains inhibition, facilitation and transfer mechanism.'),(2,'Modellaktivität nicht mit persönlichem Schmerz gleichgesetzt.','Does not equate modeled activity with personal pain.')])],
'Candidate explicitly distinguishes nociception from pain and peripheral/spinal/descending processing, with compassionate no-provocation limits. No literal HE pain competency asserted; source hold remains.')

add(3,'representation',[
('Schall wird mechanisch zur Cochlea übertragen; Haarzellen transduzieren Bewegung in elektrische Rezeptorsignale.','Sound is mechanically transmitted to the cochlea; hair cells transduce movement into electrical receptor signals.','Verfolgt Trommelfell, Gehörknöchelchen, cochleäre Bewegung und Haarzellantwort ohne Schall im Nerv.','Traces eardrum, ossicles, cochlear motion and hair-cell response without treating nerve signals as sound.'),
('Der Hörnerv und zentrale Relais leiten/verarbeiten Information bis zur Hörrinde; zentrale Bahnen sind beidseitig verschaltet.','Auditory nerve and central relays convey/process information to auditory cortex; central pathways include bilateral connections.','Zeichnet eine vereinfachte Hörbahn mit Hirnstamm, Thalamus und Cortex ohne Ein-Ohr-eine-Hemisphäre-Fehlschluss.','Draws a simplified route via brainstem, thalamus and cortex without an ear-to-one-hemisphere misconception.'),
('Frequenzinformation hängt mit dem Ort cochleärer Bewegung zusammen; verschiedene Unterbrechungen betreffen andere Stufen.','Frequency information relates to cochlear location; different disruptions affect different stages.','Begründet Frequenzort und Funktionsfolgen aus gegebenen Modellbedingungen mit Diagnosegrenze.','Justifies frequency location and functional effects from supplied model conditions with a diagnostic limit.')],
[('Tiefe/hohe Frequenz und mechanische/neuronale Stufe.','Low/high frequency and mechanical/neural stage.'),('Periphere Übertragung gegenüber zentraler Verarbeitung.','Peripheral transmission versus central processing.')],[
case('hearing-route',('Vom Schall zur Hörrinde','From sound to auditory cortex'),
('Karten: Luftschwingung; Trommelfell; Gehörknöchelchen; Flüssigkeit/Basilarmembran der Cochlea; Haarzelle; Hörnerv; Hirnstamm; Thalamus; Hörrinde. Gegeben: hohe Frequenzen vor allem cochleäre Basis, tiefe vor allem Spitze. Reife Haarzellen liefern graduelle Rezeptorantworten; afferente Nervenfasern Aktionspotenziale.','Cards: air vibration; eardrum; ossicles; cochlear fluid/basilar membrane; hair cell; auditory nerve; brainstem; thalamus; auditory cortex. Given: high frequencies mainly cochlear base, low mainly apex. Mature hair cells produce graded receptor responses; afferent nerve fibers produce action potentials.'),
('Ordne und erkläre die Übergänge. Vergleiche zwei Töne unterschiedlicher Frequenz und begrenze das Schema.','Order and explain transitions. Compare two tones of different frequency and bound the diagram.'),
('Luft → Trommelfell → Knöchelchen → cochleäre Bewegung → verbogene Haarbündel/Rezeptorantwort → synaptische Erregung afferenter Fasern → Hörnerv → Hirnstamm → thalamisches Relais → Hörrinde. Der hohe Ton aktiviert vor allem Basis, der tiefe Spitze. Der Nerv transportiert elektrische Aktivität, keine Luftschwingung. Mehrere Relais und beidseitige Verbindungen sind vereinfacht.','Air → eardrum → ossicles → cochlear movement → deflected hair bundles/receptor response → synaptic activation of afferent fibers → auditory nerve → brainstem → thalamic relay → auditory cortex. High tone activates mainly base, low tone apex. Nerves convey electrical activity, not air vibration. Multiple relays and bilateral connections are simplified.'),
('Die mechanische Cochleaantwort bleibt erhalten, aber die Haarzell-Synapse zur afferenten Faser ist blockiert. Was fehlt danach?','Mechanical cochlear response remains, but the hair-cell synapse to afferent fiber is blocked. What is missing downstream?'),
('Mechanische Antwort allein ersetzt den neuronalen Übergang nicht. Entsprechende afferente Aktionspotenziale und nachfolgende Information fehlen im Modell.','Mechanical response cannot replace the neural transition. Corresponding afferent action potentials and downstream information are absent in the model.'),
('Keine echten Lautstärkeversuche; kein klinischer Hörtest.','No real loudness experiments or clinical hearing test.'),[(4,'Mechanisch-elektrischer Übergang fachlich korrekt.','Scientifically correct mechanical/electrical transition.'),(4,'Zentrale Route und Frequenzort korrekt.','Correct central route and frequency location.'),(2,'Beidseitigkeit und Modellgrenze benannt.','States bilateral connections and model limit.')]),
case('hearing-blocks',('Stufen unterscheiden','Distinguish stages'),
('Drei unabhängige fiktive Modelle bei gleichem Schall: A reduziert nur die Bewegung des Trommelfells; B lässt diese Bewegung normal, verringert Haarzellantworten; C erhält periphere Antworten, stört aber eine zentrale Verbindung. Alle anderen angegebenen Stufen bleiben im jeweiligen Modell gleich.','Three independent fictitious models at identical sound input: A reduces only eardrum movement; B preserves movement but reduces hair-cell responses; C preserves peripheral responses but disrupts a central connection. Other stipulated stages stay unchanged in each model.'),
('Erkläre jeweils, wo die Weiterleitung geändert wird. Warum reicht eine verminderte Wahrnehmung allein nicht zur Unterscheidung?','Explain where transmission changes in each model. Why does reduced perception alone not distinguish them?'),
('A betrifft mechanische Zuführung und dadurch nachfolgende Reizung; B die Transduktion bei erhaltenem Eingang; C die zentrale Weiterleitung/Verarbeitung bei erhaltenem peripherem Signal. Alle können Information reduzieren, aber an verschiedenen Stufen. Vergleichbare Wahrnehmung beweist keine gleiche Ursache; zusätzliche stufenbezogene Messungen wären nötig.','A affects mechanical input and therefore downstream stimulation; B affects transduction despite preserved input; C affects central transmission/processing despite preserved peripheral signals. All can reduce information at different stages. Similar perception does not establish the same cause; stage-specific measurements would be required.'),
('Eine Seite fällt peripher aus. Ist deswegen eine ganze Hörrinde sicher stumm? Begründe mit einer zusätzlichen Regel: zentrale Hörbahnen erhalten Eingänge beider Ohren.','One peripheral side fails. Is an entire auditory cortex necessarily silent? Use the additional rule that central auditory pathways receive input from both ears.'),
('Nein. Wegen beidseitiger zentraler Eingänge kann Information des anderen Ohres ankommen. Der Ausfall kann trotzdem Hörleistung und räumliches Hören beeinträchtigen; genaue Folgen sind nicht vorgegeben.','No. Bilateral central input allows information from the other ear to arrive. Hearing performance and localization can still be impaired; exact effects are not stipulated.'),
('Keine individuelle Diagnose; Schutz vor Lärm nicht durch absichtliche Lärmbelastung testen.','No individual diagnosis; do not test noise protection by intentional exposure.'),[(4,'A/B/C stufenbezogen erklärt.','Explains A/B/C by stage.'),(4,'Informationsverlust und beidseitiger Transfer begründet.','Justifies information loss and bilateral transfer.'),(2,'Keine klinische Sicherheit aus einem Modell behauptet.','Avoids clinical certainty from a model.')])],
'Candidate covers sound transduction, afferent transmission and bilateral central processing in two full applications. Literal HE invented subsection is not endorsed; current course/source holds separate.')

add(4,'experiment',[
('Der Aufbau ausgewählter Sinnesorgane ermöglicht Aufnahme und Umwandlung verschiedener Reize.','Selected sense-organ structures enable reception and transduction of different stimuli.','Verknüpft beim Auge und Ohr wesentliche Strukturen mit ihren Funktionen.','Links essential eye and ear structures with functions.'),
('Reizleitung, Transduktion und nervöse Weiterleitung sind verschiedene Schritte.','Stimulus transmission, transduction and neural conduction are distinct steps.','Erklärt vergleichend den Übergang von Licht beziehungsweise Schwingung zu neuronaler Information.','Explains the transition from light or vibration to neural information by comparison.'),
('Sichere Modellbeobachtungen erlauben begrenzte Struktur-Funktions-Aussagen, keine vollständige Prüfung echter Sinnesorgane.','Safe model observations support limited structure/function inferences, not complete testing of real sense organs.','Plant einen kontrollierten Modellvergleich und nennt eine nicht dargestellte Funktion.','Plans a controlled model comparison and identifies an unrepresented function.')],
[('Auge/Ohr und Reizart.','Eye/ear and stimulus modality.'),('Organstruktur versus sicheres physikalisches Modell.','Organ structure versus safe physical model.')],[
case('sense-eye',('Licht auf die Netzhaut','Light onto the retina'),
('Auge-Modell mit Linse und rückwärtigem Schirm: Bei gleichem Gegenstand erzeugt Einstellung A ein scharfes Bild auf dem Schirm, B ein unscharfes. Der Schirm stellt die Netzhautlage dar; keine lebenden Augen, keine Laser oder direkte Sonnenbeobachtung.','Eye model with lens and posterior screen: for the same object, setting A gives a sharp image on the screen, B a blurred image. Screen represents retinal location; no living eyes, lasers or direct observation of the sun.'),
('Erkläre Hornhaut/Linse, Iris, Netzhaut und Sehnerv. Plane einen Vergleich, der nur die Linseneinstellung verändert.','Explain cornea/lens, iris, retina and optic nerve. Plan a comparison changing only lens setting.'),
('Hornhaut/Linse bündeln Licht, Iris reguliert den Lichteinfall. Netzhautrezeptoren transduzieren; der Sehnerv leitet neuronale Information. Gegenstandsabstand, Helligkeit und Schirmposition konstant, Linseneinstellung variieren und Bildschärfe vergleichen. Das Schirmmodell zeigt optische Abbildung, aber keine Rezeptorantwort oder Wahrnehmung.','Cornea/lens focus light, iris regulates its amount. Retinal receptors transduce; optic nerve carries neural information. Keep object distance, brightness and screen position constant; vary lens setting and compare sharpness. Screen model demonstrates optics, not receptor response or perception.'),
('Ein hellerer Gegenstand bleibt bei B unscharf. Warum ersetzt mehr Licht die passende Fokussierung nicht?','A brighter object stays blurred at B. Why does more light not replace appropriate focusing?'),
('Helligkeit verändert Lichtmenge, nicht den Ort des Fokus. Bildschärfe benötigt passende Brechung und Netzhautlage; Iris und Linse haben unterschiedliche Aufgaben.','Brightness changes light quantity, not focal location. Sharpness requires suitable refraction and retinal location; iris and lens have different functions.'),
('Nur Modell; kein Sehtest oder Nachweis einer Fehlsichtigkeit.','Model only; not an eye test or evidence of a refractive defect.'),[(4,'Struktur-Funktion aller vier Elemente korrekt.','Correct functions of all four structures.'),(4,'Kontrollierter Vergleich und Transfer erklärt.','Explains controlled comparison and transfer.'),(2,'Optikmodell von Transduktion/Wahrnehmung getrennt.','Separates optics model from transduction/perception.')]),
case('sense-ear',('Mechanik und Rezeptoren vergleichen','Compare mechanics and receptors'),
('Modell mit leichter Membran, Hebeln und bewegtem Wasser, ohne Lautsprecher. Ein identischer sanfter mechanischer Impuls bewegt A (Membran frei), bei B ist die Membran festgehalten. Modell stellt Trommelfell, Knöchelchen und Flüssigkeit vereinfacht dar; Haarzellen sind nicht eingebaut.','Model with light membrane, levers and moving water, no loudspeaker. Identical gentle mechanical input moves A with free membrane; B holds membrane fixed. Model represents eardrum, ossicles and fluid simply; hair cells are absent.'),
('Erkläre Ohrfunktion vom Reiz bis zum Nerv, plane A/B kontrolliert und vergleiche die Rezeptoren mit dem Auge.','Explain ear function from stimulus to nerve, plan controlled A/B comparison, and compare receptors with those in the eye.'),
('Schall bewegt Trommelfell und Knöchelchen; cochleäre Bewegung verbiegt Haarbündel und verändert Rezeptorsignale. Synaptische Übertragung erregt den Hörnerv. Bei gleichem Impuls, Hebel und Wasserstand prüft A/B die mechanische Übertragung. Auge transduziert Licht, Ohr Bewegung; beide erzeugen neuronale Information. Das Modell beweist keine Haarzellantwort.','Sound moves eardrum and ossicles; cochlear movement bends hair bundles and changes receptor signals. Synaptic transmission activates auditory nerve. With matched input, levers and water level, A/B tests mechanical transmission. Eye transduces light, ear movement; both create neural information. Model does not demonstrate hair-cell responses.'),
('Ein Modell lässt Wasser schwingen, enthält aber keine Rezeptorzelle. Ist damit Hören nachgewiesen?','A model makes water move but contains no receptor cell. Does this demonstrate hearing?'),
('Nein: nur Mechanik. Transduktion, nervöse Verarbeitung und Wahrnehmung fehlen. Ein passendes Rezeptor-/Nervenmodell wäre zusätzlich nötig.','No: mechanics only. Transduction, neural processing and perception are absent. An appropriate receptor/nerve model would additionally be required.'),
('Keine Lärm- oder Gehörbelastung; keine Aussage über echte Versuchspersonen.','No noise exposure or claim about actual participants.'),[(4,'Ohrmechanik und Haarzell/Nervenübergang korrekt.','Correct ear mechanics and receptor/nerve transition.'),(4,'Kontrolle und Augenvergleich begründet.','Justifies control and eye comparison.'),(2,'Wasserbewegung nicht als Hörnachweis gewertet.','Does not treat water motion as proof of hearing.')])],
'Candidate explains two selected organs and includes safe controlled model planning for the investigate operator; no actual experiment or human release claimed.')

add(5,'representation',[
('Großhirn, Kleinhirn und Hirnstamm erfüllen unterschiedliche, verbundene Funktionen.','Cerebrum, cerebellum and brainstem perform distinct connected functions.','Ordnet die drei Hauptbereiche korrekt und beschreibt Wahrnehmung/Denken, Koordination und grundlegende Regulation.','Locates three principal regions and describes perception/thought, coordination and basic regulation.'),
('Wichtige weitere Bereiche wirken als Relais, Regulations- und Gedächtnisnetzwerke.','Other important regions participate in relay, regulation and memory networks.','Beschreibt Thalamus, Hypothalamus und Hippocampus überblicksartig ohne exklusive Zentrenbehauptung.','Describes thalamus, hypothalamus and hippocampus in overview without exclusive-center claims.'),
('Eine Übersicht ordnet Funktionen, ersetzt aber keine vollständige Verarbeitungserklärung oder Diagnose.','An overview organizes functions without replacing full processing explanations or diagnosis.','Begründet Zusammenarbeit mehrerer Bereiche an einer Tätigkeit und begrenzt Orts-Funktions-Zuordnungen.','Justifies cooperation among regions in an activity and bounds region/function associations.')],
[('Äußere Hauptbereiche und innere Strukturen.','External principal regions and internal structures.'),('Übersichtstabelle und Alltagssituation.','Overview table and everyday situation.')],[
case('brain-overview',('Hirnbereiche ordnen','Organize brain regions'),
('Unbeschriftete schematische Seitenansicht: großer gefalteter oberer Bereich; kleiner gefalteter hinterer/unterer Bereich; abwärts ziehender Stiel davor. Funktionskarten: Wahrnehmen/Denken; Koordination/Anpassung von Bewegungen; grundlegende vegetative Funktionen und Leitungswege.','Unlabeled schematic lateral view: large folded upper region; smaller folded posterior/lower region; downward stalk in front of it. Function cards: perception/thought; coordination/adaptation of movement; basic autonomic functions and pathways.'),
('Beschrifte Großhirn, Kleinhirn und Hirnstamm, ordne die Karten zu und erkläre Zusammenarbeit beim Radfahren.','Label cerebrum, cerebellum and brainstem, assign cards and explain cooperation during cycling.'),
('Großhirn oben: Wahrnehmung und Denken; Kleinhirn hinten/unten: Koordination/Anpassung; Hirnstamm nach unten: grundlegende Regulation und Verbindungen. Beim Radfahren werden Umgebung verarbeitet, Bewegung geplant/koordiniert sowie Atmung/Kreislauf reguliert. Kein Bereich erledigt die ganze Tätigkeit allein.','Cerebrum above: perception/thought; cerebellum posterior/below: coordination/adaptation; brainstem downward: basic regulation and connections. Cycling combines environmental processing, movement planning/coordination and breathing/circulatory regulation. No region performs the whole activity alone.'),
('Beim stillen Lesen bewegen sich die Beine kaum. Ist das Kleinhirn deshalb generell funktionslos?','During quiet reading the legs hardly move. Is the cerebellum therefore generally inactive?'),
('Nein. Die Übersicht nennt Schwerpunkte, keine Ausschließlichkeiten; unter anderem Augenbewegungen und weitere Netzwerkbeiträge bleiben möglich. Aus fehlender Beinbewegung folgt keine vollständige Inaktivität.','No. The overview identifies major roles, not exclusive ones; eye movements and other network contributions remain possible. Absent leg movement does not establish total inactivity.'),
('Überblick, kein Aktivierungsscan und keine Patientendiagnose.','Overview, not an activation scan or patient diagnosis.'),[(4,'Topologie und drei Funktionsschwerpunkte richtig.','Correct topology and three main functions.'),(4,'Zusammenarbeit und Transfer nicht exklusiv erklärt.','Explains cooperation and non-exclusive transfer.'),(2,'Übersichtsgrenze deutlich.','States overview limit.')]),
case('brain-inner',('Innere Bereiche im Überblick','Internal regions in overview'),
('Karten: Thalamus = wichtiges Relais vieler sensorischer Informationen; Hypothalamus = Regulation unter anderem Temperatur, Hunger und Verbindung zum Hormonsystem; Hippocampus-Netzwerk = Beteiligung an neuen episodischen Erinnerungen. Aufgabenbeispiele: auf einen Ton achten, Körpertemperatur regulieren, neuen Schulweg lernen.','Cards: thalamus = important relay for many sensory inputs; hypothalamus = regulation including temperature/hunger and connection to endocrine system; hippocampal network = participation in new episodic memories. Examples: attend to a sound, regulate temperature, learn a new school route.'),
('Ordne passende Beiträge zu, ergänze Großhirn/Kleinhirn/Hirnstamm und widerlege die Aussage, alle Erinnerungen lägen nur im Hippocampus.','Assign relevant contributions, add principal regions, and challenge the claim that all memories are located only in hippocampus.'),
('Ton: thalamisches Relais und kortikale Verarbeitung; Temperatur: hypothalamische Regulation mit weiteren Ausführungswegen; neuer Weg: Hippocampus-Netzwerk mit verteilten kortikalen Netzwerken. Großhirn verarbeitet, Kleinhirn koordiniert Bewegungsanteile, Hirnstamm verbindet/reguliert. Hippocampus unterstützt neue episodische Inhalte, ist kein alleiniger Speicher aller Erinnerungsformen.','Sound: thalamic relay and cortical processing; temperature: hypothalamic regulation with downstream pathways; new route: hippocampal network with distributed cortical networks. Cerebrum processes, cerebellum coordinates movement aspects, brainstem connects/regulates. Hippocampus supports new episodic content, not exclusive storage of every memory type.'),
('Ein Tier reguliert Hunger und navigiert zu Futter. Reicht ein einziges Bereichsetikett zur Erklärung?','An animal regulates hunger and navigates to food. Is one region label enough to explain this?'),
('Nein: Regulation, Wahrnehmung, Gedächtnis, Planung und Bewegung greifen zusammen. Hypothalamus ist ein passender Regulationsbeitrag, nicht die gesamte Erklärung.','No: regulation, perception, memory, planning and movement cooperate. Hypothalamus contributes to regulation but is not the complete explanation.'),
('Funktionsübersicht ohne detaillierte Bahnanalyse oder medizinische Schlussfolgerung.','Functional overview without detailed pathway analysis or medical inference.'),[(4,'Drei inneren Funktionen korrekt zugeordnet.','Correctly assigns three internal functions.'),(4,'Hauptbereiche integriert und Alleinspeicherung widerlegt.','Integrates principal regions and rejects exclusive storage.'),(2,'Zusammenarbeit statt Ein-Etikett-Erklärung.','Explains cooperation rather than one label.')])],
'Overview candidate kept distinct from processing/disruption goal; correct gross topology and distributed functions, not a clinical localization test.')

add(6,'experiment',[
('Ein Attrappenvergleich verändert einen Auslösereiz kontrolliert und beobachtet eine definierte Reaktion.','A dummy comparison changes a candidate releasing stimulus under control and observes a defined response.','Legt konstant gehaltene Attrappenmerkmale, Reaktion und Wiederholungen fest.','Specifies constant dummy features, response and repetitions.'),
('Reaktion hängt auch von inneren Bedingungen ab; ein Reiz wirkt nicht zwangsläufig in jedem Zustand gleich.','Responses also depend on internal conditions; a stimulus need not act identically in every state.','Vergleicht Reiz und vorgegebenen inneren Zustand getrennt anhand der Daten.','Compares stimulus and stipulated internal state separately using data.'),
('Beobachtete Muster erlauben begrenzte Verhaltensbeschreibungen ohne Absichts- oder Universalitätsbehauptung.','Observed patterns support bounded behavioral descriptions without claims about intention or universality.','Deutet Wiederholungsdaten und nennt eine Kontroll- und Tierschutzgrenze.','Interprets repeated observations and states a control and animal-welfare limit.')],
[('Attrappenmerkmal und innerer Zustand.','Dummy feature and internal state.'),('Annäherung gegenüber Pickreaktion; andere fiktive Tierart.','Approach versus pecking response; different fictitious species.')],[
case('dummy-fish',('Reiz und Fortpflanzungszustand','Stimulus and reproductive state'),
('Synthetische Fischbeobachtung je zehn Videosequenzen: identische Attrappenform/Größe, Bauch rot oder grau. Territorialer Fortpflanzungszustand: Annäherungen rot 8, grau 2. Außerhalb dieses Zustands: rot 2, grau 1. Reihenfolge zufällig; kein lebender Fisch wird provoziert.','Synthetic fish observation, ten video sequences each: identical dummy shape/size, belly red or gray. Territorial reproductive state: approaches red 8, gray 2. Outside that state: red 2, gray 1. Random order; no live fish is provoked.'),
('Vergleiche innerhalb und zwischen Zuständen. Beschreibe das Zusammenspiel und eine notwendige Kontrolle.','Compare within and across states. Describe interaction and one required control.'),
('Im territorialen Zustand unterscheiden sich rot/grau stärker (8/2) als außerhalb (2/1). Rot ist im Modell ein relevanter Auslösereiz; innerer Zustand beeinflusst die Reaktionsbereitschaft. Gleiche Form, Abstand, Präsentationsdauer und Reihenfolgekontrolle verhindern einfache Alternativerklärungen. Kein Beweis eines bewussten Ärgerns oder universeller Aggression.','Red/gray differ more in territorial state (8/2) than outside (2/1). Red is a relevant releasing stimulus in the model; internal state changes responsiveness. Matched shape, distance, duration and order control limit simple alternatives. This does not prove conscious annoyance or universal aggression.'),
('Neue Daten bei anderem Abstand: rot 8 aus der Nähe, grau 2 aus großer Entfernung. Ist der Farbeffekt jetzt isoliert?','New data: red gives 8 approaches nearby; gray 2 far away. Is color now isolated?'),
('Nein. Abstand ist ein zusätzlicher veränderter Faktor. Beide Farben müssen bei gleichen Abständen verglichen werden.','No. Distance is another changed factor. Both colors must be compared at matched distances.'),
('Erfundene Daten; keine echten Attrappenversuche oder Verallgemeinerung auf alle Fische.','Invented data; no actual dummy experiment or generalization to all fish.'),[(4,'Vergleich 8/2 und 2/1 korrekt.','Correctly compares 8/2 and 2/1.'),(4,'Innerer Zustand und Reiz mit Kontrolle getrennt.','Separates state and stimulus with control.'),(2,'Keine Absichts-/Tierartenverallgemeinerung.','Avoids intention/species generalization.')]),
case('dummy-bird',('Pickreaktion kontrolliert beschreiben','Describe pecking under control'),
('Fiktive Jungvogel-Videos, je zehn gleiche Beobachtungsfenster: schnabelförmige Attrappe mit/ohne roten Punkt. Kurz vor normaler Fütterung: Pickreaktionen mit Punkt 7, ohne 2; kurz nach normaler Fütterung: 2 und 1. Keine Futterentziehung; gleiche Form und Bewegung.','Fictitious chick videos, ten matched observation windows: bill-shaped dummy with/without red spot. Before normal feeding: peck responses 7 with spot, 2 without; after feeding: 2 and 1. No food deprivation; matched shape and movement.'),
('Erkläre Unterschiede mit Auslösereiz und innerem Zustand und plane einen verbesserten Vergleich mit Wiederholungen.','Explain differences using stimulus and internal state and plan an improved repeated comparison.'),
('Punkt und Fütterungszustand wirken im Datensatz zusammen; vor Fütterung ist der Unterschied stärker. Wiederholte unabhängige Beobachtungen, zufällige Reihenfolge und gleiche Fenster/Form/Bewegung prüfen Stabilität. Normale Versorgung bleibt erhalten. Daten allein zeigen nicht, was ein Jungvogel denkt oder dass nur die Farbe wichtig wäre.','Spot and feeding state interact in the dataset; difference is larger before feeding. Independent repeated observations, random order and matched windows/shape/movement test stability. Normal care is preserved. Data do not show what chicks think or establish that only color matters.'),
('Beim Wiederholen verändern sich Form und Punkt gleichzeitig. Welche Schlussfolgerung wird unsicher?','A repeat changes shape and spot together. Which conclusion becomes uncertain?'),
('Ein isolierter Punkteffekt: Form könnte beitragen. Für die Trennung nur jeweils ein Merkmal ändern oder beide Faktoren systematisch kombinieren.','An isolated spot effect: shape may contribute. Change one feature at a time or combine factors systematically to separate them.'),
('Kein reales Tierexperiment; Hunger nicht durch schädigende Entziehung herstellen.','No real animal experiment; do not create hunger through harmful deprivation.'),[(4,'Reiz/Zustand anhand beider Datenreihen erklärt.','Explains stimulus/state using both data series.'),(4,'Wiederholungen und Confound-Kontrolle sinnvoll.','Appropriate repetitions and confound control.'),(2,'Versorgungs- und Beobachtungsgrenze benannt.','States care and observation limits.')])],
'Two full safe synthetic observation/dummy cases cover observe, compare and describe stimulus/state interaction. HB learning-conditions mapping is not newly accepted as dummy evidence.')

add(7,'experiment',[
('Konditionierung erfordert einen geplanten Zusammenhang von Reiz/Ereignis oder Verhalten/Folge.','Conditioning requires a planned relationship between stimulus/events or behavior/consequence.','Entwirft gepaarte oder kontingente Bedingungen und eine geeignete Kontrolle.','Designs paired or contingent conditions and an appropriate control.'),
('Messung und Kontrolle müssen Lernen von bloßer Wiederholung, Ermüdung oder zufälligem Auftreten unterscheiden.','Measurement and control must distinguish learning from repetition, fatigue or chance.','Definiert Ausgangsmessung, Wiederholungen, Reaktionsmaß und alternative Erklärungen.','Defines baseline, repetitions, response measure and alternatives.'),
('Vergleiche menschlicher/anderer Lernfähigkeit benötigen vergleichbare Anforderungen und Grenzen.','Comparisons of human/other learning require comparable demands and limits.','Plant einen fairen ungefährlichen Vergleich ohne universelles Fähigkeitsranking.','Plans a fair harmless comparison without a universal ability ranking.')],
[('Klassische Paarung versus operante Kontingenz.','Classical pairing versus operant contingency.'),('Artgerechtes Lernmaß und geeignete Vergleichsbedingungen.','Species-appropriate learning measure and comparable conditions.')],[
case('conditioning-pair',('Paarung planen','Plan pairing'),
('Nur virtueller Versuchsplan: Eine neutrale Tonfolge soll vor einer normalen Futteranzeige erscheinen. Gemessen wird Annäherung an deren Ort während des Tons. Zu Beginn löst der Ton keine erhöhte Annäherung aus; alle Gruppen erhalten gleiche Anzahlen Ton und Futteranzeige.','Virtual design only: neutral tone precedes a normal food display. Measure approach to its location during the tone. Initially tone does not increase approach; groups receive identical counts of tone and food display.'),
('Plane Paarung/Kontrolle, Messzeitpunkte und einen Test ohne Futteranzeige. Wie wäre ein fairer Vergleich mit Menschen möglich?','Plan pairing/control, measurement times and a test without food display. How could a fair human comparison be designed?'),
('Versuchsgruppe Ton kurz vor Anzeige, Kontrolle zeitlich ungepaart bei gleichen Häufigkeiten. Ausgangswert, wiederholte Durchgänge und Ton-allein-Test vergleichen; erhöhte selektive Tonantwort unterstützt Lernen der Beziehung. Menschen im freiwilligen virtuellen Spiel mit passendem Zielreiz prüfen, nicht rohe Reaktionszahlen verschiedener Bedürfnisse vergleichen. Gleiche Grundlogik, vergleichbares Maß und individuelle Variation beachten.','Experimental group: tone shortly before display; control: unpaired timing with matched counts. Compare baseline, repeated trials and tone-only test; increased selective response supports learning the relationship. Humans can use a voluntary virtual game with suitable target event; do not compare raw responses with different needs. Match design logic and measure; allow individual variation.'),
('Auch ungepaarte Kontrollen zeigen mehr Annäherung. Reicht das als spezifischer Konditionierungsnachweis?','Unpaired controls also show more approach. Is that sufficient evidence of specific conditioning?'),
('Nein. Allgemeine Aktivierung oder Übung könnte beide erklären. Relevant ist ein verlässlicher Unterschied zur passenden Kontrolle und eine tonbezogene Antwort.','No. General arousal or practice could explain both. A reliable difference from appropriate controls and a tone-specific response are relevant.'),
('Hypothetisch/virtuell, freiwillig; keine aversiven Reize oder Tierbelastung.','Hypothetical/virtual and voluntary; no aversive stimuli or animal burden.'),[(4,'Paarung, gleiche Ereignismengen und Kontrolle richtig.','Correct pairing, matched event counts and control.'),(4,'Ausgangs-/Transfermessung und fairer Vergleich.','Baseline/transfer measurement and fair comparison.'),(2,'Alternativen und Sicherheit eingegrenzt.','Bounds alternatives and safety.')]),
case('conditioning-action',('Folge an Verhalten binden','Link consequence to behavior'),
('Virtuelles Lernspiel: Aktion A oder B kann gewählt werden. Nur A soll einen nicht-materiellen Spielpunkt auslösen. Kontrollgruppe erhält gleiche Punktefolge zeitlich, aber unabhängig von eigenen Aktionen. Ausgangswahlhäufigkeit A/B wird erhoben.','Virtual learning game: choose action A or B. Only A should produce a non-material game point. Control receives same temporal point sequence independent of its own actions. Baseline A/B choices are recorded.'),
('Plane einen operanten Vergleich und erkläre, wie ein andersartiges Lebewesen unter ungefährlichen Modellbedingungen fair verglichen würde.','Plan an operant comparison and explain a fair harmless model comparison with another organism.'),
('Kontingenz A→Punkt gegen zeitlich gekoppelte, aktionsunabhängige Kontrolle; gleiche Dauer/Punktmenge. Wahlanteil A über Durchgänge und beim neuen Tastenort erfassen. Zunahme nur unter Kontingenz stützt Folgenlernen. Bei anderer Art passende verfügbare Aktionen/Reize verwenden und relative Änderung zur Ausgangslage vergleichen. Kein Schluss auf allgemein höhere oder niedrigere Intelligenz.','Compare contingent A→point with temporally matched action-independent control; match duration/point counts. Track A choice proportion across trials and at new button location. Increase specifically under contingency supports consequence learning. For another species use suitable available actions/stimuli and compare change from baseline. Do not infer globally higher/lower intelligence.'),
('Im Transfer werden A und B räumlich getauscht. Wie trennt das gelernte Aktionssignal von einer bloßen Ortsvorliebe?','In transfer, swap A and B positions. How does this separate learned action cue from a location preference?'),
('Weiterhin A wählen trotz Ortswechsel passt zum Aktionssignal; gleiche Stelle wählen passt eher zu Ortsbindung. Beide müssen unter denselben Regeln verglichen werden.','Choosing A despite relocation fits the action cue; choosing the old location fits location dependence. Compare under matched rules.'),
('Plan ohne echte Durchführung; keine heimlichen Lerntests, Belohnungsentziehung oder Gesundheitsaussagen.','Plan without actual execution; no covert testing, deprivation or health claims.'),[(4,'Kontingenz und passende Kontrolle korrekt.','Correct contingency and matched control.'),(4,'Verhaltensmaß, Ortswechsel und Artvergleich begründet.','Justifies measure, relocation and species comparison.'),(2,'Keine universelle Intelligenzrangfolge oder Erprobungsbehauptung.','No universal intelligence ranking or trial claim.')])],
'Two complete experiment-planning candidates for classical and operant learning preserve the operator and comparative-learning demand, without actual human/animal experiments.')

add(8,'data',[
('Beobachtungsdaten können genetische und erworbene Beiträge stützen, aber nicht ohne Weiteres vollständig trennen.','Observations can support genetic and acquired contributions without necessarily separating them completely.','Formuliert eine abgestufte Aussage anhand kontrollierter Vergleiche statt einer absoluten Entweder-oder-Zuordnung.','Makes a graded claim using controlled comparisons rather than an absolute either/or classification.'),
('Aufzucht, Erfahrung, Alter und Motivation sind mögliche alternative Einflüsse.','Rearing, experience, age and motivation are possible alternative influences.','Prüft relevante Kontrollen und erklärt die begrenzte Aussagekraft erster Beobachtungen.','Checks relevant controls and explains limits of first observations.'),
('Anlage und Lernen können zusammenwirken; Veränderbarkeit widerlegt genetische Beiträge nicht.','Genetic background and learning can interact; changeability does not disprove genetic contributions.','Überträgt die Datenbeurteilung auf ein neues Design und nennt verbleibende Unsicherheit.','Transfers data assessment to a new design and states remaining uncertainty.')],
[('Herkunftsgruppe und kontrollierte Aufzucht/Erfahrung.','Origin group and controlled rearing/experience.'),('Erstes Auftreten versus Veränderung nach Training.','First occurrence versus change after training.')],[
case('behavior-rearing',('Herkunft und Erfahrung','Origin and experience'),
('Fiktive Tierart, keine reale Studie: Zwei Herkunftslinien X/Y zeigen in gleicher Aufzucht bei erster geprüfter Wahl mittlere Wegpräferenzen 8/10 bzw. 3/10 für links. Nach gleichem Training auf rechts: X 4/10, Y 1/10 links. Alter und Versorgungsbedingungen gleich; erste Prüfung bedeutet nicht erfahrungsfreies Leben.','Fictitious species, not a real study: origin lines X/Y with matched rearing show 8/10 versus 3/10 mean left choices at first test. After matched rightward training: X 4/10, Y 1/10 left. Matched age/care; first test does not mean an experience-free life.'),
('Beurteile genetische und erworbene Anteile mit Daten und zwei Grenzen.','Assess genetic and acquired contributions using data and two limitations.'),
('Unterschiede X/Y unter gleicher Aufzucht passen zu Herkunftseinflüssen, beweisen aber keinen bestimmten Genmechanismus: vorgeburtliche oder nicht kontrollierte Erfahrungen bleiben möglich. Abnahme nach Training in beiden Linien stützt Erfahrungsbeeinflussbarkeit. Verhalten ist im Modell weder rein angeboren noch vollständig beliebig erlernt. Gruppendaten und kleine Stichprobe erlauben keine sichere Individualvorhersage.','X/Y differences under matched rearing fit origin-related effects but do not prove a specific genetic mechanism: prenatal or uncontrolled experience remains possible. Decline after training in both lines supports experience-dependent change. Modeled behavior is neither purely innate nor wholly arbitrary learning. Group data and small samples do not give certain individual predictions.'),
('Neues Design: X wächst in Umgebung U, Y in V auf. Warum wäre eine gleiche Ausgangsdifferenz jetzt weniger eindeutig?','New design: X grows up in U and Y in V. Why would the same baseline difference now be less clear?'),
('Herkunft und Umgebung sind gekoppelt. Beide Herkunftslinien müssten in U und V oder in vergleichbaren kontrollierten Bedingungen verglichen werden.','Origin and environment are confounded. Both lines must be compared in U and V or under comparable controlled conditions.'),
('Keine reale Zucht, genetische Festlegung oder Rangfolge menschlicher Gruppen.','No actual breeding, genetic determinism or ranking of human groups.'),[(4,'Beide Zahlenänderungen sinnvoll genutzt.','Uses both numeric changes appropriately.'),(4,'Anlage/Erfahrung und Confound differenziert.','Distinguishes origin/experience and confounding.'),(2,'Erste Prüfung und Individualvorhersage begrenzt.','Bounds first-test and individual inference.')]),
case('behavior-training',('Lernen oder Reifung?','Learning or maturation?'),
('Synthetischer Altersvergleich: gleich alte trainierte Tiere treffen eine neue Zuordnung im Mittel 8/10, untrainierte 4/10; vor Training beide 4/10. Versorgung, Prüfzeit und Gelegenheit zur sozialen Beobachtung gleich. Die Zuordnung war vorher für alle unbekannt.','Synthetic age-matched comparison: trained animals solve a new association at mean 8/10, untrained 4/10; baseline both 4/10. Matched care, testing time and social-observation opportunities. Association previously unknown to all.'),
('Beurteile, welcher Verhaltensanteil durch die Daten als erworben gestützt wird. Sind Gene damit unwichtig?','Assess which behavioral component is supported as acquired. Do the data make genes irrelevant?'),
('Die verbesserte neue Zuordnung bei trainierter Gruppe gegenüber gleicher Ausgangslage und altersgleicher Kontrolle stützt Lernen dieser Zuordnung. Reifung allein erklärt den Gruppenunterschied unter diesen Regeln nicht. Biologische Lernvoraussetzungen und andere Einflüsse bleiben; ein erworbener Beitrag bedeutet nicht fehlende genetische Beteiligung.','Improvement in the trained group relative to matched baseline and age control supports learning this association. Maturation alone does not explain the difference under these conditions. Biological learning capacities and other influences remain; an acquired contribution does not imply no genetic involvement.'),
('Ohne Alterskontrolle ist die trainierte Gruppe älter. Wie ändert sich die Schlussfolgerung?','Without age control, the trained group is older. How does the conclusion change?'),
('Alter/Reifung wird zur Alternative. Für spezifischen Trainingseinfluss braucht man altersgleiche Kontrollen oder ein anderes Design, das Alter und Training trennt.','Age/maturation becomes an alternative. A specific training effect needs age-matched controls or a design separating age and training.'),
('Keine Aussage, dass alle Verhaltensweisen so erklärt oder alle Arten gleich lernfähig sind.','Does not explain all behaviors this way or establish identical learning across species.'),[(4,'Erworbene Zuordnung datenbezogen beurteilt.','Assesses acquired association using data.'),(4,'Reifungskontrolle und genetische Voraussetzungen differenziert.','Distinguishes maturation control and biological capacities.'),(2,'Verallgemeinerung begrenzt.','Bounds generalization.')])],
'Candidate judges evidence for interacting genetic/acquired components using two causal-control designs; no absolute deterministic or human-group inference.')

add(9,'modeling',[
('Insulin und Glucagon sind Signale der Bauchspeicheldrüse und regulieren Aufnahme/Speicherung beziehungsweise vor allem hepatische Freisetzung.','Insulin and glucagon are pancreatic signals regulating uptake/storage and primarily hepatic release, respectively.','Verfolgt gegensinnige Rückkopplung mit Leber und Muskel ohne Hormone als Glucoseträger darzustellen.','Traces opposing feedback via liver/muscle without depicting hormones as glucose carriers.'),
('Insulinwirkung ist zellabhängig; Glucagon bewirkt keine allgemeine Glucoseabgabe aller Gewebe.','Insulin action differs among cells; glucagon does not cause glucose export from every tissue.','Begründet am Modell erhöhte/verringerte Blutglucose und unterscheidet Leber- von Muskelfunktion.','Explains raised/lowered blood glucose and distinguishes liver from muscle function.'),
('Typ-1- und Typ-2-Diabetes haben unterschiedliche Mechanismen; Lebensgewohnheiten und Veranlagung sind multifaktorielle Zusammenhänge.','Type 1 and type 2 diabetes involve different mechanisms; lifestyle and predisposition have multifactorial relationships.','Erklärt die Mechanismen und interpretiert Risikodaten ohne Schuldzuweisung, Diagnose oder genetische Unvermeidlichkeit.','Explains mechanisms and risk data without blame, diagnosis or genetic inevitability.')],
[('Hohe/niedrige Modellglucose und gestörte Insulinwirkung.','High/low modeled glucose and impaired insulin action.'),('Mechanismus Typ1/Typ2 und Beobachtungszusammenhang.','Type1/type2 mechanism and observational association.')],[
case('glucose-feedback',('Gegensinnige Rückkopplung','Opposing feedback'),
('Qualitatives Modell, keine Blutmesswerte: Bei erhöhtem Glucoseangebot steigt Insulinsignal aus Betazellen; bei niedrigem Angebot steigt Glucagonsignal aus Alphazellen. Leber kann Glucose speichern oder ins Blut freisetzen; Muskel/Fett steigern insulinabhängige Aufnahme. Gehirn/Rote Blutkörperchen sind Beispiele, deren Aufnahme nicht einfach von Insulin abhängt.','Qualitative model, not blood measurements: increased glucose availability raises beta-cell insulin signal; low availability raises alpha-cell glucagon signal. Liver can store or release glucose into blood; muscle/fat increase insulin-dependent uptake. Brain/red blood cells provide examples of uptake not simply dependent on insulin.'),
('Zeichne beide Rückkopplungen und erkläre, warum Glucagon nicht als allgemeine Glucoseabgabe aus Muskeln dargestellt werden darf.','Draw both feedback loops and explain why glucagon must not be shown as general muscle glucose export.'),
('Hohe Glucose → Insulin → Aufnahme/Speicherung in passenden Geweben, Leberfreisetzung vermindert → Glucose sinkt → Insulinreiz sinkt. Niedrige Glucose → Glucagon → vor allem Leberfreisetzung → Glucose steigt → Glucagonreiz sinkt. Muskel nutzt gespeicherte Glucose vor allem selbst; Glucagon gehört im Schema zur Leber, nicht zur allgemeinen Gewebeabgabe. Hormone sind Steuerungssignale.','High glucose → insulin → uptake/storage in appropriate tissues and reduced hepatic release → glucose falls → insulin stimulus declines. Low glucose → glucagon → mainly hepatic release → glucose rises → glucagon stimulus declines. Muscle primarily uses its stored glucose locally; glucagon in this diagram acts via liver, not general tissue export. Hormones are control signals.'),
('Insulin ist vorhanden, die Zielgewebe reagieren schwächer. Erkläre die mögliche Folge bei gleichem Angebot.','Insulin is present but target tissues respond less. Explain a possible consequence at equal input.'),
('Aufnahme/Speicherung und Unterdrückung hepatischer Freisetzung wirken schwächer; Glucose kann länger erhöht bleiben. Zusätzliche Insulinproduktion kann anfangs kompensieren, muss aber nicht dauerhaft genügen.','Uptake/storage and suppression of hepatic release are weaker; glucose can remain elevated longer. Extra insulin production may initially compensate but need not remain sufficient.'),
('Keine individuellen Messwerte, Dosen, Grenzwerte oder Therapieempfehlung.','No individual measurements, doses, thresholds or treatment advice.'),[(4,'Beide Rückkopplungen korrekt und geschlossen.','Both feedback loops correct and closed.'),(4,'Leber/Muskel sowie Resistenz unterschieden.','Distinguishes liver/muscle and resistance.'),(2,'Signalrolle und zellabhängige Aufnahme korrekt.','Correct signal role and cell-dependent uptake.')]),
case('diabetes-risk',('Mechanismen und Risikozusammenhänge','Mechanisms and risk associations'),
('Fiktive Vergleichsdaten ohne Patient:innen: A autoimmunbedingter Betazellverlust mit sehr wenig Insulin; B reduzierte Insulinantwort der Gewebe plus unzureichende Kompensation. In einer synthetischen Bevölkerungsbeobachtung ist Typ2 häufiger bei familiärer Vorbelastung und geringer Bewegung; Alter, Versorgung und weitere Faktoren sind nicht vollständig kontrolliert.','Fictitious comparison without patients: A autoimmune beta-cell loss with very little insulin; B reduced tissue response to insulin plus insufficient compensation. In synthetic population observation, type2 is more common with family history and low activity; age, care and other factors are not fully controlled.'),
('Ordne A/B Typ1/Typ2 zu, erkläre den Regelkreisfehler und beurteile Zusammenhang von Veranlagung und Lebensgewohnheiten.','Assign A/B to type1/type2, explain regulation failures and assess predisposition/lifestyle associations.'),
('A passt zu Typ1: Verlust insulinbildender Zellen, nicht schlicht zu viel Zucker. B passt zu Typ2: Resistenz mit unzureichender Sekretionskompensation. Beide beeinträchtigen die Regulation auf andere Weise. Familiengeschichte und Aktivität können Risikofaktoren anzeigen, beweisen in dieser Beobachtung aber keine einzelne Ursache oder Diagnose. Veranlagung bedeutet nicht Unvermeidlichkeit, Lebensgewohnheiten nicht Schuld.','A fits type1: loss of insulin-producing cells, not simply excess sugar. B fits type2: resistance with insufficient secretory compensation. Both impair regulation differently. Family history/activity can indicate risk factors but this observation proves neither a single cause nor diagnosis. Predisposition is not inevitability, lifestyle is not blame.'),
('Eine Person ohne familiäre Vorbelastung ist wenig aktiv. Darf daraus Typ2 diagnostiziert oder ausgeschlossen werden?','A person without family history is inactive. Can type2 be diagnosed or excluded from that?'),
('Weder noch. Risikofaktoren ändern Wahrscheinlichkeiten, entscheiden aber nicht den individuellen Befund. Diagnose benötigt geeignete medizinische Untersuchung, die das Unterrichtsmodell nicht liefert.','Neither. Risk factors affect probabilities but do not determine individual findings. Diagnosis requires appropriate medical assessment, absent from this teaching model.'),
('Keine private Gesundheitsdaten, individuelle Diagnose, moralische Wertung oder Ernährungsberatung.','No private health data, individual diagnosis, moral judgment or dietary advice.'),[(4,'Typ1/Typ2 und Mechanismen korrekt.','Correct type1/type2 mechanisms.'),(4,'Multifaktorielle Risiken/Confounder und Transfer begründet.','Justifies multifactorial risks/confounders and transfer.'),(2,'Keine Schuld, Determinierung oder Diagnose behauptet.','No blame, determinism or diagnosis claim.')])],
'Candidate covers pancreatic feedback and multifactorial diabetes mechanisms with official NIDDK fact checks and no medical/patient acceptance claim.')

